/* Datos comprimidos para distribución web. Regenerar desde las fuentes originales. */
(() => {
  const b64 = "";
  const binary = atob(b64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
  window.MEMORIAS_CSV = pako.inflate(bytes, { to: 'string' });
})();
